select case when sqft >= 12694 then 'PREMIUM' else 'STANDARD' end as sqft_tier, date_trunc('week', opened_date) as week_start, stddev_samp(sqft) as sqft_stddev, approx_percentile(sqft, array(0.25, 0.5, 0.75)) as sqft_quartiles, count(case when region = 'Central' then 1 end) as central_count from stores group by sqft_tier, week_start having stddev_samp(sqft) > 0 order by week_start
